{
  "summary": "The customer called to downgrade their expensive plan to a cheaper one. The agent processed a change to the basic 499 rupees plan, but the customer was dissatisfied with the price. The plan change request was submitted with a confirmation SMS pending.",
  "reasons": [
    {
      "evidence": [
        {
          "turn_id": 2,
          "quote": "Mera current plan nahi chal raha hai, it is too expensive and I need to change it to a cheaper one."
        }
      ],
      "label": "plan_change",
      "confidence": 1.0,
      "rationale": "The customer explicitly stated they want to change their plan to a cheaper one."
    }
  ],
  "resolution": {
    "evidence": [
      {
        "turn_id": 7,
        "quote": "I have updated your account."
      },
      {
        "turn_id": 11,
        "quote": "I will process the plan change and send a confirmation SMS to your phone."
      }
    ],
    "status": "partial",
    "confidence": 0.9,
    "rationale": "The plan change request was processed and submitted, but the customer remained unhappy with the price and the conversation ended without full satisfaction."
  },
  "churn": {
    "evidence": [
      {
        "turn_id": 10,
        "quote": "Yeh toh bahut galat hai! I am very disappointed with your service."
      },
      {
        "turn_id": 12,
        "quote": "SMS toh theek hai, but I am not happy with this price. This is totally unfair!"
      }
    ],
    "risk_score": 0.4,
    "flag": false,
    "rationale": "The customer expressed strong disappointment and unhappiness with the pricing, but did not explicitly state an intent to cancel, switch, or port out."
  }
